class CLIPSimulator:
    def encode_image(self, tags: list[str]) -> set:
        words = set()
        for tag in tags:
            words.update(w.lower() for w in str(tag).split())
        return words

    def encode_text(self, label: str) -> set:
        return {w.lower() for w in label.split()}

    def similarity(self, image_tags: list[str], label: str) -> float:
        img = self.encode_image(image_tags)
        txt = self.encode_text(label)
        union = img | txt
        if not union:
            return 0.0
        return len(img & txt) / len(union)

    def classify(self, image_tags: list[str], candidate_labels: list[str]) -> list[dict]:
        if not candidate_labels:
            return []
        sims = [self.similarity(image_tags, lab) for lab in candidate_labels]
        total = sum(sims)
        if total == 0:
            scores = [1.0 / len(candidate_labels)] * len(candidate_labels)
        else:
            scores = [s / total for s in sims]
        results = [{"label": lab, "score": sc} for lab, sc in zip(candidate_labels, scores)]
        results.sort(key=lambda r: r["score"], reverse=True)
        return results


# Test it:
clip = CLIPSimulator()
image = ["dog", "playing", "fetch", "park", "grass"]
labels = ["a dog playing fetch", "a cat sleeping", "a car on road"]

results = clip.classify(image, labels)
print(results[0]["label"])
print(len(results))
print(f"{sum(r['score'] for r in results):.1f}")

class ImageSearchEngine:
    def __init__(self):
        self.images = []

    def index(self, images: list[dict]):
        self.images = [{"path": img["path"], "tags": list(img["tags"])} for img in images]

    def _jaccard(self, set_a: set, set_b: set) -> float:
        union = set_a | set_b
        if not union:
            return 0.0
        return len(set_a & set_b) / len(union)

    def search(self, query: str, top_k: int = 3) -> list[dict]:
        words = set(query.lower().split())
        results = []
        for img in self.images:
            tags = {t.lower() for t in img["tags"]}
            results.append({"path": img["path"], "score": self._jaccard(words, tags)})
        results.sort(key=lambda r: r["score"], reverse=True)
        return results[:top_k]

    def auto_tag(self, image_tags: list[str], all_tags: list[str], threshold: float = 0.2) -> list[str]:
        img = {t.lower() for t in image_tags}
        scored = []
        for tag in all_tags:
            score = self._jaccard(img, set(tag.lower().split()))
            if score >= threshold:
                scored.append((score, tag))
        scored.sort(reverse=True)
        return [tag for _, tag in scored]


engine = ImageSearchEngine()
engine.index([
    {"path": "beach_sunset.jpg", "tags": ["beach", "sunset", "ocean", "sand"]},
    {"path": "city_night.jpg", "tags": ["city", "night", "lights", "buildings"]},
    {"path": "dog_park.jpg", "tags": ["dog", "park", "grass", "playing"]},
])

results = engine.search("sunset at the beach", top_k=2)
print(results[0]["path"])
print(len(results))

matched = engine.auto_tag(
    ["beach", "sunset", "waves"],
    ["beach scenery", "mountain view", "ocean sunset", "indoor photo"],
    threshold=0.2
)
print(matched[0])
